CREATE TABLE agriculture_expenses (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, farm_id BIGINT UNSIGNED NOT NULL, crop_id BIGINT UNSIGNED NULL, financial_transaction_id BIGINT UNSIGNED NULL, expense_date DATE NOT NULL, expense_type ENUM('seeds','fertilizer','pesticide','labor','equipment','irrigation','transport','other') NOT NULL, amount DECIMAL(15,2) NOT NULL, description VARCHAR(500) NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uq_agriculture_expenses_ft (financial_transaction_id), KEY idx_ae_farm_date (farm_id,expense_date), CONSTRAINT chk_ae_amount CHECK (amount > 0), CONSTRAINT fk_ae_farm FOREIGN KEY (farm_id) REFERENCES farms(id) ON DELETE RESTRICT, CONSTRAINT fk_ae_crop FOREIGN KEY (crop_id) REFERENCES crops(id) ON DELETE RESTRICT, CONSTRAINT fk_ae_ft FOREIGN KEY (financial_transaction_id) REFERENCES financial_transactions(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
